<?php

declare(strict_types=1);

namespace Seampact\Laravel\Tests;

use Illuminate\Foundation\Application;
use Illuminate\Support\Facades\Facade;
use Illuminate\Support\Facades\Route;
use PHPUnit\Framework\TestCase;
use Seampact\Codegen\Runtime\RuntimeVersion;

/** The version check refuses every boot of an api generated by another version, except the command that regenerates it. */
final class RegenerationTest extends TestCase
{
    /** @var array<array-key, mixed>|null */
    private ?array $argumentsBefore = null;

    protected function setUp(): void
    {
        $this->argumentsBefore = is_array($_SERVER['argv'] ?? null) ? $_SERVER['argv'] : null;
    }

    protected function tearDown(): void
    {
        Facade::clearResolvedInstances();
        Facade::setFacadeApplication(null);
        $_SERVER['argv'] = $this->argumentsBefore;
    }

    public function testTheGenerateCommandBootsUnderARuntimeVersionMismatch(): void
    {
        $_SERVER['argv'] = ['artisan', 'seampact:generate'];
        $application = new Application(sys_get_temp_dir());
        Facade::setFacadeApplication($application);
        $provider = new ForeignVersionServiceProvider($application);

        $provider->register();
        $provider->boot();
        Route::macroCall('seampact', ['tasks']);

        $this->addToAssertionCount(1);
    }

    public function testAnyOtherBootRefusesARuntimeVersionMismatch(): void
    {
        $_SERVER['argv'] = ['artisan', 'route:list'];
        $provider = new ForeignVersionServiceProvider(new Application(sys_get_temp_dir()));

        $this->expectException(\LogicException::class);
        $this->expectExceptionMessage(RuntimeVersion::GENERATED_FOR_OTHER_VERSION);
        $provider->register();
    }
}
